import itertools

def all_intervals(n):
    for perm in itertools.permutations(range(n)):
        diffs = set()
        for i in range(n-1):
            diffs.add(abs(perm[i+1] - perm[i]))
        if diffs == set(range(1, n)):
            return perm
    return None

print(all_intervals(4))
